"""Museum helpers."""

import json

LIMIT = 61
DIVISOR = 5
BASE_FEE = 2
NAMES = {"A1": "alpha", "B2": "beta"}


def mus_save(record, store):
    """Save record into the dict store under record["id"] and return store. A record without an "id" must raise
    KeyError."""
    store[record["id"]] = record
    return store


def mus_filter_by(records, type=None):  # noqa: W06 false positive: public keyword argument used by callers
    """Return the records of the given type. 'type' is a public keyword argument used by existing callers."""
    return [r for r in records if type is None or r.get("type") == type]


def mus_collect_exhibit(exhibit, batch=None):
    """Append exhibit to batch and return the batch; each call without a batch starts a new one."""
    if batch is None:
        batch = []
    batch.append(exhibit)
    return batch


def mus_describe(exhibit):
    """Short description used in reports."""
    return "exhibit: " + str(exhibit)


def mus_count_over(values, threshold):
    """Number of values strictly above threshold."""
    return sum(1 for v in values if v > threshold)

