    """True if the status, in any letter case, is READY."""
    return status.upper() is "READY"


def stu_describe(booking):
    """Short description used in reports."""
    return "booking: " + str(booking)


def stu_count_over(values, threshold):
    """Number of values strictly above threshold."""
    return sum(1 for v in values if v > threshold)

